import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Dashboard({ token }) {
  const [balance, setBalance] = useState({ balance: 0, connected: false });
  const [trades, setTrades] = useState([]);
  const [summary, setSummary] = useState({ totalTrades: 0, totalProfit: 0, winRate: 0 });
  const [newTrade, setNewTrade] = useState({ symbol: 'R_100', side: 'BUY', amount: 10, duration: 60 });
  const [loading, setLoading] = useState(false);

  useEffect(() => { fetchBalance(); fetchTrades(); fetchSummary(); }, []);

  const fetchBalance = async () => {
    const res = await axios.get('http://localhost:5000/api/trading/balance', { headers: { Authorization: `Bearer ${token}` } });
    setBalance(res.data);
  };
  const fetchTrades = async () => {
    const res = await axios.get('http://localhost:5000/api/trading/trades', { headers: { Authorization: `Bearer ${token}` } });
    setTrades(res.data);
  };
  const fetchSummary = async () => {
    const res = await axios.get('http://localhost:5000/api/trading/summary', { headers: { Authorization: `Bearer ${token}` } });
    setSummary(res.data);
  };
  const executeTrade = async () => {
    setLoading(true);
    try {
      await axios.post('http://localhost:5000/api/trading/trade', newTrade, { headers: { Authorization: `Bearer ${token}` } });
      alert('Trade executed! 3% platform fee applied.');
      fetchBalance(); fetchTrades(); fetchSummary();
    } catch (err) { alert('Trade failed: ' + err.response?.data?.error); }
    setLoading(false);
  };

  return (
    <div className="dashboard">
      <div className="stats-grid">
        <div className="stat-card"><h3>Deriv Balance</h3><div className="stat-value">{balance.connected ? `${balance.balance} ${balance.currency || 'USD'}` : 'Not Connected'}</div>{!balance.connected && <a href="http://localhost:5000/api/auth/deriv/login" className="connect-btn">Connect Deriv</a>}</div>
        <div className="stat-card"><h3>Total P/L</h3><div className={`stat-value ${summary.totalProfit >= 0 ? 'positive' : 'negative'}`}>${summary.totalProfit?.toFixed(2) || '0.00'}</div></div>
        <div className="stat-card"><h3>Win Rate</h3><div className="stat-value">{summary.winRate}%</div></div>
        <div className="stat-card"><h3>Total Trades</h3><div className="stat-value">{summary.totalTrades}</div></div>
      </div>
      <div className="trade-panel"><h2>Execute Trade <span className="fee-badge">+3% Platform Fee</span></h2>
        <div className="trade-form">
          <select value={newTrade.symbol} onChange={e => setNewTrade({...newTrade, symbol: e.target.value})}><option value="R_10">R_10</option><option value="R_25">R_25</option><option value="R_50">R_50</option><option value="R_75">R_75</option><option value="R_100">R_100</option></select>
          <select value={newTrade.side} onChange={e => setNewTrade({...newTrade, side: e.target.value})}><option value="BUY">🟢 CALL (Price Up)</option><option value="SELL">🔴 PUT (Price Down)</option></select>
          <input type="number" placeholder="Amount (USD)" value={newTrade.amount} onChange={e => setNewTrade({...newTrade, amount: parseFloat(e.target.value)})} />
          <input type="number" placeholder="Duration (ticks)" value={newTrade.duration} onChange={e => setNewTrade({...newTrade, duration: parseInt(e.target.value)})} />
          <button onClick={executeTrade} disabled={loading || !balance.connected}>{loading ? 'Processing...' : `Place ${newTrade.side} Order (+3% fee)`}</button>
        </div>
      </div>
      <div className="trades-table"><h2>Recent Trades</h2>
        <table><thead><tr><th>Symbol</th><th>Side</th><th>Amount</th><th>Fee</th><th>P/L</th><th>Status</th><th>Date</th></tr></thead>
        <tbody>{trades.map(t => (<tr key={t._id}><td>{t.symbol}</td><td className={t.side === 'BUY' ? 'buy' : 'sell'}>{t.side}</td><td>${t.amount}</td><td className="fee">${t.platformFee?.toFixed(2) || '0'}</td><td className={t.profitLoss >= 0 ? 'positive' : 'negative'}>${t.profitLoss?.toFixed(2) || '—'}</td><td>{t.status}</td><td>{new Date(t.openedAt).toLocaleString()}</td></tr>))}</tbody></table>
      </div>
    </div>
  );
}
